import{_ as t,o as s,c as i,ag as e}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"gh_attach.py — GitHub 附件上传脚本","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/gh-attach-script.md","filePath":"topics/ai-system-architecture/gh-attach-script.md"}'),l={name:"topics/ai-system-architecture/gh-attach-script.md"};function h(n,a,o,r,p,c){return s(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="gh-attach-py-—-github-附件上传脚本" tabindex="-1">gh_attach.py — GitHub 附件上传脚本 <a class="header-anchor" href="#gh-attach-py-—-github-附件上传脚本" aria-label="Permalink to &quot;gh_attach.py — GitHub 附件上传脚本&quot;">​</a></h1><blockquote><p>状态：可用脚本 · 依赖 gh CLI（需已 <code>gh auth login</code>） 端点：未官方文档化</p></blockquote><h2 id="位置" tabindex="-1">位置 <a class="header-anchor" href="#位置" aria-label="Permalink to &quot;位置&quot;">​</a></h2><p><code>scripts/gh_attach.py</code></p><h2 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p>把图片/文件上传成 GitHub 附件,返回可粘贴进 Issue/PR/Comment 的 markdown。</p><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 图片 → 输出 markdown 图</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/gh_attach.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo.png</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> owner/repo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --label</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;截图说明&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 非图片 → 输出链接</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/gh_attach.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report.pdf</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> owner/repo</span></span></code></pre></div><h2 id="原理" tabindex="-1">原理 <a class="header-anchor" href="#原理" aria-label="Permalink to &quot;原理&quot;">​</a></h2><p>调用未文档化端点：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST https://uploads.github.com/user-attachments/assets</span></span>
<span class="line"><span>    ?name=&lt;文件名&gt;&amp;content_type=&lt;MIME&gt;&amp;repository_id=&lt;仓库数字ID&gt;</span></span>
<span class="line"><span>Authorization: Bearer &lt;token&gt;</span></span></code></pre></div><ul><li>token：优先 <code>GH_TOKEN</code> 环境变量，否则 <code>gh auth token</code></li><li>repository_id：用 <code>gh api repos/&lt;owner/repo&gt; --jq .id</code> 获取</li></ul><h2 id="✅-实测结论-2026-08-06-已验证" tabindex="-1">✅ 实测结论（2026-08-06 已验证） <a class="header-anchor" href="#✅-实测结论-2026-08-06-已验证" aria-label="Permalink to &quot;✅ 实测结论（2026-08-06 已验证）&quot;">​</a></h2><ol><li><strong>调用会成功</strong>：POST 返回 HTTP 200 + JSON 含 <code>asset_url</code>（如 <code>https://github.com/user-attachments/assets/&lt;uuid&gt;</code>）</li><li>⚠️ <strong>该 asset_url 独立访问是从 404</strong>——它必须在被嵌进真实的 Issue/PR/Comment 正文后才&quot;激活&quot;（和拖拽上传行为一致）。这是 GitHub 附件机制的正常表现，不代表失败。</li></ol><h2 id="⚠️-风险" tabindex="-1">⚠️ 风险 <a class="header-anchor" href="#⚠️-风险" aria-label="Permalink to &quot;⚠️ 风险&quot;">​</a></h2><ul><li>该端点为<strong>非官方/未文档化</strong>，作者原话 &quot;for now&quot;，未来可能失效</li><li>只建议在 CI/自动化里当&quot;锦上添花&quot;，别把它当唯一上传途径</li><li>视频等大文件未测试，MIME 判断对图片可靠</li></ul><h2 id="与相关推断" tabindex="-1">与相关推断 <a class="header-anchor" href="#与相关推断" aria-label="Permalink to &quot;与相关推断&quot;">​</a></h2><ul><li>你说的&quot;区别靠 carrier...&quot;: GitHub 上传其实也有类似逻辑——上传成功与否不只看 HTTP 状态，要看是否&quot;真正可用&quot;。本脚本已诚实标注独立 404 这个坑。</li></ul><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h2><ul><li>Ben Sheldon 博客 2026-08-03：Programmatically upload attachments to GitHub</li><li>出自 Intercom 的 2x-skills attach-github-assets 思路</li></ul>`,20)])])}const k=t(l,[["render",h]]);export{u as __pageData,k as default};
